 import { openStore } from "../db/store.js";
 import { router } from "./router.js";
 import { itemRoutes } from "./routes/items.js";
@@ -17,11 +17,28 @@ import { safetyRoutes } from "./routes/safety.js";

 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language");
+  let language = config.defaultLanguage;
+  let bestQuality = 0;
+  for (const entry of String(header?.[1] ?? "").split(",")) {
+    const preference = /^([a-z]+)(?:-[a-z0-9]+)*(?:\s*;\s*q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?|\.\d{1,3}))?$/i.exec(entry.trim());
+    if (!preference) continue;
+    const candidate = preference[1].toLowerCase();
+    const quality = Number(preference[2] ?? 1);
+    if (quality > bestQuality && LANGUAGES.includes(candidate)) {
+      language = candidate;
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
