-      log.error("unhandled", { message: e.message });
-      return { status: 500, body: errorBody("internal", "Something went wrong.") };
+      if (!(e instanceof AppError)) log.error("unhandled", { message: e.message });
+      const error = e instanceof AppError ? e : new AppError("internal");
+      return { status: error.status, body: errorBody(error.code, t(error.code, lang, error.params)) };
     }
   };
 }
